contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test function
    // params: caller (address that will be the jojoTeam), senderIsTeam (whether this contract sets jojoTeam to that caller), desc
    // We cannot change msg.sender when calling c (calls come from this contract), but C has a public jojoTeam variable we can set only by interacting with c's storage indirectly.
    // However the only way to make this contract be the jojoTeam is if the freshly deployed C already has jojoTeam equal to address(this) or some external setup — the checker deploys a fresh C and provides it to constructor.
    // To make a useful, provable property given constraints, we observe behavior based on current jojoTeam value read from c.

    function run(address caller, bool tryAsTeam, string calldata description) public payable {
        // Read current jojoTeam from c
        address currentTeam = c.jojoTeam();

        // We will attempt to call newEmergencyOracle; call will succeed iff currentTeam == address(this)
        // But the contract's onlyJojoTeam requires msg.sender == jojoTeam. Our msg.sender is this InvMutTest contract.
        // So call should succeed only when currentTeam == address(this).

        bool reverted;
        // Make the deciding call
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If call reverted then jojoTeam was not this contract; if it didn't revert then jojoTeam must equal this contract.
        // General rule: reverted == (currentTeam != address(this))
        assert(reverted == (currentTeam != address(this)));
    }

    receive() external payable {}
}
